{% if not paid %}<div class="c b">{{ _("PRO FORMA - NOT A RECEIPT") }}</div>{% endif %}
<hr>
<table>
{% if doc.name is string and doc.name | trim %}<tr><td>{{ _("Check") }}</td><td class="mv">{{ doc.name | e }}</td></tr>{% endif %}
{% if doc.custom_ury_order_number is string and doc.custom_ury_order_number | trim %}<tr><td>{{ _("Order") }}</td><td class="mv">#{{ doc.custom_ury_order_number | e }}</td></tr>{% endif %}
{% if _date_str %}<tr><td>{{ _("Date") }}</td><td class="mv">{{ _date_str | e }}{% if _time_str %} {{ _time_str | e }}{% endif %}</td></tr>{% endif %}
