{% for _is_tax, _rows in [(false, sc_rows), (true, tax_rows)] %}{% for _r in _rows %}{% if _r.tax_amount is number and _r.tax_amount %}{% set _rate_s = ((_r.rate | int) if (_r.rate == (_r.rate | int)) else _r.rate) | string if (_r.rate is number and _r.rate) else "" %}{% set _desc_s = (_r.description | string) if (_r.description is defined and _r.description) else "" %}<tr><td{% if _is_tax %} class="sub"{% endif %}>{{ _r.description | striptags | e }}{% if _rate_s and (_rate_s ~ "%") not in _desc_s %} ({{ _rate_s }}%){% endif %}{% if _is_tax and _r.included_in_print_rate %} {{ _("(incl.)") }}{% endif %}</td><td class="a{% if _is_tax %} sub{% endif %}">{{ _r.get_formatted("tax_amount", doc) }}</td></tr>{% endif %}{% endfor %}{% endfor %}
