<div class="c b">{{ _("MERGED CHECK") }}: {{ doc.custom_merged_pos_invoice | e }}</div>
<table>
<tr><td class="q b">{{ _("Qty") }}</td><td class="b">{{ _("Item") }}</td><td class="a b">{{ _("Amount") }}</td></tr>
{% for row in doc.custom_merged_pos_invoice_details %}
<tr>
