{% if bill_ef.issued %}<tr><td>{{ _("Issued") }}</td><td class="mv">{{ bill_ef.issued | e }}</td></tr>{% endif %}
{% if bill_ef.is_return and bill_ef.original_fdn %}<tr><td>{{ _("Original FDN") }}</td><td class="mv">{{ bill_ef.original_fdn | e }}</td></tr>{% endif %}
{% if bill.tax_id is string and bill.tax_id | trim %}<tr><td>{{ _("Buyer TIN") }}</td><td class="mv">{{ bill.tax_id | e }}</td></tr>{% endif %}
